document.querySelector('.menu-toggle')?.addEventListener('click',function(){const open=document.querySelector('.nav').classList.toggle('open');this.setAttribute('aria-expanded',String(open))});
const form=document.querySelector('#siteSearch');
if(form){const field=document.querySelector('#searchQuery'),list=document.querySelector('#searchResults'),count=document.querySelector('#searchCount');let entries=[];field.value=new URLSearchParams(location.search).get('q')||'';const render=()=>{const terms=field.value.toLowerCase().trim().split(/\s+/).filter(Boolean);const matches=entries.filter(x=>terms.every(t=>(x.title+' '+x.description).toLowerCase().includes(t)));list.replaceChildren();count.textContent=matches.length?matches.length+' pages found':'No matching pages. Try PNG, logo, photo, or pricing.';for(const item of matches){const article=document.createElement('article'),h=document.createElement('h2'),a=document.createElement('a'),p=document.createElement('p');article.className='content-card';a.href=item.url;a.textContent=item.title;p.textContent=item.description;h.append(a);article.append(h,p);list.append(article)}};form.addEventListener('submit',e=>{e.preventDefault();history.replaceState(null,'',location.pathname+'?q='+encodeURIComponent(field.value));render()});fetch('/search-index.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{entries=data;render()}).catch(()=>{count.textContent='Search is unavailable. Please use the conversion guides linked below.'})}
